insert into public.menu_items (category_id, slug, name, vn, description, price, image_url, badges, option_group_keys, sort, visible, available) select id, 'pho-beef', 'Beef Phở', 'Phở bò', 'A hearty bowl of Vietnamese beef phở with tender, medium rare slices of marbled beef, smooth rice noodles and a rich, slow simmered broth infused with star anise, cinnamon and herbs.', 16.90, 'beef-pho.jpg', array['Best seller']::text[], array['pho-addons']::text[], 0, true, true from public.menu_categories where slug = 'pho' on conflict (slug) do nothing;
