insert into public.menu_items (category_id, slug, name, vn, description, price, image_url, badges, option_group_keys, sort, visible, available) select id, 'pho-ribeye', 'Ribeye Phở', 'Phở đặc biệt', 'Our phở crowned with a whole ribeye steak, simmered gently in fragrant broth and served medium rare. A luxurious take on the classic, rich in beefy flavour with a melt in your mouth texture.', 21.80, 'ribeye-pho.jpg', array['Premium']::text[], array['pho-addons']::text[], 2, true, true from public.menu_categories where slug = 'pho' on conflict (slug) do nothing;
