insert into public.menu_items (category_id, slug, name, vn, description, price, image_url, badges, option_group_keys, sort, visible, available) select id, 'pho-pork', 'Pork Phở', 'Phở thịt lợn', 'Our own creation: a comforting bowl of pork phở with tender pork slices and silky rice noodles in a rich, fragrant pork broth slow simmered to perfection.', 14.90, 'pork-pho.jpg', array['House creation']::text[], array['pho-addons']::text[], 4, true, true from public.menu_categories where slug = 'pho' on conflict (slug) do nothing;
