insert into public.menu_categories (slug, title, vn, blurb, note, sort, visible) values ('banh-mi', 'Bánh Mì', 'Bánh mì', 'Our artisan Vietnamese baguette is lighter and airier than a French baguette, with a crisp, thin crust and a soft, fluffy inside. Toasted and filled to order.', 'Freshly made, made for you', 1, true) on conflict (slug) do nothing;
